import hashlib
import json
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import parse_qs, urlsplit

source = Path('products/distribution/sqlite-bespoke-inquiry/live-baseline.html')
output = source.with_name('live-intake-reading-evidence.json')
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '1dbcaa64a3f399c03612ce1c999e342fc901727ed4889bfee83a0afc7bcd78db'

class IntakeParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.blocks = []
        self.templates = []
        self.active = []

    def handle_starttag(self, tag, attrs):
        if tag in {'h1', 'h2', 'h3', 'p', 'li', 'pre'}:
            self.active.append((tag, []))
        if tag == 'a':
            href = dict(attrs).get('href') or ''
            if href.lower().startswith('mailto:'):
                fields = parse_qs(urlsplit(href).query, keep_blank_values=True)
                self.templates.append({key: fields.get(key, []) for key in ('subject', 'body')})

    def handle_data(self, data):
        for _, parts in self.active:
            parts.append(data)

    def handle_endtag(self, tag):
        if self.active and self.active[-1][0] == tag:
            _, parts = self.active.pop()
            text = ' '.join(''.join(parts).split())
            if text:
                self.blocks.append({'tag': tag, 'text': text})

parser = IntakeParser()
parser.feed(raw.decode('utf-8'))
terms = ('diagnos', 'correct', 'expected', 'attendu', 'before', 'after', 'avant', 'après', 'mailto', 'email', 'courriel', 'synth', 'case', 'cas ')
selected = [block for block in parser.blocks if any(term in block['text'].casefold() for term in terms)]
report = {'source_receipt': 'TASK-179548560100', 'source_sha256': digest, 'candidate_passages': selected, 'decoded_mailto_queries': parser.templates, 'coverage': 'Selected HTML text and decoded subject/body fields from the saved public baseline. Judge equivalent English and French wording against the full page. No email client or delivery was tested.'}
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'path': str(output), 'passages': len(selected), 'templates': len(parser.templates)}))
